//! 实例类型 (InstanceType): 16 位堆对象类型编号。
//!
//! 编号由 metagen 求解器 (tools/metagen/instance_types.py, 即 Torque
//! instance-type-generator.cc 的移植) 从头文件 V8_IT_* 注解求解得出,
//! ABI 锚点 (v8-internal.h: kJSObjectType 等) 生成期已断言全部命中。
//! 字符串类型 (bit7=0) 硬编码段在前, 其余按继承层级区间排布。

use crate::error::{Error, Result};

// ── 字符串 tag 位域 (instance-type.h:25-114) ───────────────────────────────
/// bit7-15 任一置位 → 非字符串。
pub const K_IS_NOT_STRING_MASK: u32 = 0xffffff80;
/// bit7=0 → 字符串。
pub const K_STRING_TAG: u32 = 0x0;
/// bit0-2: 字符串表示。
pub const K_STRING_REPRESENTATION_MASK: u32 = 0x7;
/// 顺序字符串。
pub const K_SEQ_STRING_TAG: u32 = 0x0;
/// cons 字符串。
pub const K_CONS_STRING_TAG: u32 = 0x1;
/// 外部字符串。
pub const K_EXTERNAL_STRING_TAG: u32 = 0x2;
/// 切片字符串。
pub const K_SLICED_STRING_TAG: u32 = 0x3;
/// thin 字符串。
pub const K_THIN_STRING_TAG: u32 = 0x5;
/// bit0: 间接字符串 (cons/sliced/thin)。
pub const K_IS_INDIRECT_STRING_MASK: u32 = 0x1;
/// bit0=1 → 间接字符串。
pub const K_IS_INDIRECT_STRING_TAG: u32 = 0x1;
/// bit2: thin 字符串专有位。
pub const K_THIN_STRING_TAG_BIT: u32 = 0x4;
/// bit3: 编码 (0=双字节, 1=单字节)。
pub const K_STRING_ENCODING_MASK: u32 = 0x8;
/// 双字节编码 tag。
pub const K_TWO_BYTE_STRING_TAG: u32 = 0x0;
/// 单字节编码 tag。
pub const K_ONE_BYTE_STRING_TAG: u32 = 0x8;
/// 表示 + 编码合并掩码。
pub const K_STRING_REPRESENTATION_AND_ENCODING_MASK: u32 =
  K_STRING_REPRESENTATION_MASK | K_STRING_ENCODING_MASK;
/// 顺序单字节。
pub const K_SEQ_ONE_BYTE_STRING_TAG: u32 = K_SEQ_STRING_TAG | K_ONE_BYTE_STRING_TAG;
/// 顺序双字节。
pub const K_SEQ_TWO_BYTE_STRING_TAG: u32 = K_SEQ_STRING_TAG | K_TWO_BYTE_STRING_TAG;
/// 外部单字节。
pub const K_EXTERNAL_ONE_BYTE_STRING_TAG: u32 = K_EXTERNAL_STRING_TAG | K_ONE_BYTE_STRING_TAG;
/// 外部双字节。
pub const K_EXTERNAL_TWO_BYTE_STRING_TAG: u32 = K_EXTERNAL_STRING_TAG | K_TWO_BYTE_STRING_TAG;
/// bit4: 外部字符串数据指针未缓存。
pub const K_UNCACHED_EXTERNAL_STRING_MASK: u32 = 0x10;
/// 未缓存 tag。
pub const K_UNCACHED_EXTERNAL_STRING_TAG: u32 = 0x10;
/// bit5: 共享字符串。
pub const K_SHARED_STRING_MASK: u32 = 0x20;
/// 共享 tag。
pub const K_SHARED_STRING_TAG: u32 = 0x20;
/// bit6: 未内部化。
pub const K_IS_NOT_INTERNALIZED_MASK: u32 = 0x40;
/// 未内部化 tag。
pub const K_NOT_INTERNALIZED_TAG: u32 = 0x40;
/// 内部化 tag。
pub const K_INTERNALIZED_TAG: u32 = 0x0;
/// 表示+编码+共享合并掩码。
pub const K_STRING_REPRESENTATION_ENCODING_AND_SHARED_MASK: u32 =
  K_STRING_REPRESENTATION_AND_ENCODING_MASK | K_SHARED_STRING_MASK;
/// cons 快捷候选掩码 (含非字符串位与非内部化位)。
pub const K_SHORTCUT_TYPE_MASK: u32 =
  K_IS_NOT_STRING_MASK | K_IS_NOT_INTERNALIZED_MASK | K_STRING_REPRESENTATION_MASK;
/// cons 快捷候选 tag。
pub const K_SHORTCUT_TYPE_TAG: u32 = K_CONS_STRING_TAG | K_NOT_INTERNALIZED_TAG;

