// ── 伪类型别名 (instance-type.h:194-219; 原版为枚举别名, Rust 枚举禁重复判别值 → const) ──
/// 伪类型: 首个 unique name (内部化字符串)。
pub const FIRST_UNIQUE_NAME_TYPE: InstanceType = InstanceType::InternalizedTwoByteString;
/// 伪类型: 末个 unique name (Symbol)。
pub const LAST_UNIQUE_NAME_TYPE: InstanceType = InstanceType::Symbol;
/// 伪类型: 非字符串类型首值 (kFirstNonstringType=0x80)。
pub const FIRST_NONSTRING_TYPE: InstanceType = InstanceType::Symbol;
/// 伪类型: 字符串类型上界 (字符串类型稀疏)。该值是字符串段空洞, 无对应变体 → 以 u16 落值。
pub const LAST_STRING_TYPE: u16 = 127;
/// 伪类型: JS_FUNCTION_WITH_PROTOTYPE_TYPE 便捷别名。
pub const JS_FUNCTION_TYPE: InstanceType = InstanceType::JSFunctionWithPrototype;
/// 伪类型: 可调用 JS 函数首值 (FIRST_JS_FUNCTION_TYPE)。
pub const FIRST_CALLABLE_JS_FUNCTION_TYPE: InstanceType = InstanceType::JSFunctionWithoutPrototype;
/// 伪类型: 可调用 JS 函数末值 (JS_CLASS_CONSTRUCTOR_TYPE - 1)。
pub const LAST_CALLABLE_JS_FUNCTION_TYPE: InstanceType = InstanceType::JSRegExpConstructor;
/// 伪类型: 需特殊属性查找的 JSReceiver 上界 (LAST_JS_SPECIAL_OBJECT_TYPE)。
pub const LAST_SPECIAL_RECEIVER_TYPE: InstanceType = InstanceType::JSSpecialApiObject;
/// 伪类型: 可能有 elements 的自定义 JSReceiver 上界 (LAST_JS_CUSTOM_ELEMENTS_OBJECT_TYPE)。
pub const LAST_CUSTOM_ELEMENTS_RECEIVER: InstanceType = InstanceType::JSPrimitiveWrapper;
/// 伪类型: FIRST_HEAP_OBJECT_TYPE 别名。
pub const FIRST_TYPE: InstanceType = InstanceType::InternalizedTwoByteString;
/// 伪类型: LAST_HEAP_OBJECT_TYPE 别名。
pub const LAST_TYPE: InstanceType = InstanceType::WasmValueObject;
/// 伪类型: BIG_INT_BASE_TYPE 别名。
pub const BIGINT_TYPE: InstanceType = InstanceType::BigIntBase;
/// 伪类型: DEPENDENT_CODE 借用 WEAK_ARRAY_LIST_TYPE。
pub const DEPENDENT_CODE_TYPE: InstanceType = InstanceType::WeakArrayList;

/// PROPERTY_DICTIONARY_TYPE: 目标配置字典类型。
/// v8_enable_swiss_name_dictionary 默认 false (BUILD.gn:425) → NAME_DICTIONARY_TYPE。
pub const PROPERTY_DICTIONARY_TYPE: InstanceType = InstanceType::NameDictionary;

/// IsShortcutCandidate: cons 且未内部化 (可被 GC 快捷)。
#[inline]
#[must_use]
pub const fn is_shortcut_candidate(ty: u16) -> bool {
  (ty as u32 & K_SHORTCUT_TYPE_MASK) == K_SHORTCUT_TYPE_TAG
}

